// Parse and validate tracking event
const body = $input.first().json.body;

if (!body || !body.event || !body.lead_id) {
  return [{ json: { error: 'Missing required fields: event, lead_id' } }];
}

const validEvents = ['open', 'click'];
if (!validEvents.includes(body.event)) {
  return [{ json: { error: `Invalid event type: ${body.event}` } }];
}

return [{
  json: {
    lead_id: body.lead_id,
    event: body.event,
    email_id: body.email_id || null,
    link_url: body.link_url || null,
    user_agent: body.user_agent || '',
    ip_address: body.ip_address || '',
    timestamp: new Date().toISOString()
  }
}];

// Filter known bots / pre-fetchers
const event = $input.first().json;
const ua = (event.user_agent || '').toLowerCase();

const BOT_PATTERNS = [
  /googlebot/i,
  /bingbot/i,
  /yahoo.*slurp/i,
  /outlook-ios/i,
  /microsoft office/i,
  /mozilla.*5\.0.*compatible/i,
  /wget/i,
  /curl/i,
  /python-requests/i,
  /go-http-client/i,
  /java/i,
  /barracuda/i,
  /proofpoint/i,
  /mimecast/i
];

const isBot = BOT_PATTERNS.some(p => p.test(ua));

return [{
  json: {
    ...event,
    is_bot: isBot
  }
}];

// Deduplicate: check if same event was already recorded in last 60 seconds
// (prevents double-counting from email clients that load images multiple times)
const event = $input.first().json;

// Build dedup key
const dedupKey = `${event.lead_id}_${event.event}_${event.email_id || 'none'}`;
const dedupWindow = 60; // seconds

return [{
  json: {
    ...event,
    dedup_key: dedupKey,
    dedup_window_seconds: dedupWindow
  }
}];

// Prepare interaction record and lead update
const event = $input.first().json;

const interaction = {
  lead_id: event.lead_id,
  type: event.event === 'open' ? 'email_opened' : 'email_clicked',
  channel: 'email',
  metadata: {
    email_id: event.email_id,
    link_url: event.link_url,
    user_agent: event.user_agent,
    ip_address: event.ip_address,
    timestamp: event.timestamp
  }
};

// Lead field to increment
const leadUpdate = {};
if (event.event === 'open') {
  leadUpdate.field = 'emails_opened';
} else if (event.event === 'click') {
  leadUpdate.field = 'emails_clicked';
}

return [{
  json: {
    lead_id: event.lead_id,
    interaction: interaction,
    lead_update_field: leadUpdate.field,
    event_type: event.event
  }
}];
